                    vll_zz += (al2 * (al2 * (vgx[(h & 2 ? (h & 1 ? 3024 : 2928) : (h & 1 ? 3216 : 2832))] - zlzk * vgx[(h & 2 ? (h & 1 ? 2928 : 2832) : (h & 1 ? 3120 : 2736))]) - (h & 2 ? 1.0 : (h & 1 ? 3.0 : 1.0)) * vgx[(h & 2 ? (h & 1 ? 2544 : 2448) : (h & 1 ? 2736 : 2352))])) * S;
                    vkl_zz += (al2 * (ak2 * vgx[(h & 2 ? (h & 1 ? 3024 : 2928) : (h & 1 ? 3216 : 2832))] - (h & 2 ? (h & 1 ? 2.0 : 1.0) : 0.0) * vgx[(h & 2 ? (h & 1 ? 2832 : 2736) : (h & 1 ? 2736 : 2352))]) - (h & 2 ? 0.0 : (h & 1 ? 1.0 : 0.0)) * (ak2 * vgx[(h & 2 ? (h & 1 ? 2544 : 2448) : (h & 1 ? 2448 : 2352))])) * S;
                    vij_zx += Ai * T1;
                    vij_xz += Aj * T0;
                    vjj_xz += Aj * T1;
                    vii_xz += Ai * T0;
                    vkl_zx += Ak * T3;
                    vkl_xz += Al * T2;
                    vll_xz += Al * T3;
                    vkk_xz += Ak * T2;
                    w = dd_cache[(h & 2 ? (h & 1 ? 2584 : 1576) : (h & 1 ? 2008 : 568))] * vgx[(h & 2 ? (h & 1 ? 1152 : 1632) : (h & 1 ? 1248 : 1344))];
                    S = w * vgx[(h & 2 ? 0 : (h & 1 ? 96 : 384))];
                    T0 = vgx[(h & 2 ? 3456 : (h & 1 ? 3648 : 4032))] * w;
                    T1 = vgx[(h & 2 ? 3464 : (h & 1 ? 3656 : 4040))] * w;
                    T2 = vgx[(h & 2 ? 3472 : (h & 1 ? 3664 : 4048))] * w;
                    T3 = vgx[(h & 2 ? 3480 : (h & 1 ? 3672 : 4056))] * w;
                    Ai = vgx[(h & 2 ? (h & 1 ? 6880 : 6112) : (h & 1 ? 6496 : 5920))];
                    Aj = vgx[(h & 2 ? (h & 1 ? 6888 : 6120) : (h & 1 ? 6504 : 5928))];
                    Ak = vgx[(h & 2 ? (h & 1 ? 6896 : 6128) : (h & 1 ? 6512 : 5936))];
                    Al = vgx[(h & 2 ? (h & 1 ? 6904 : 6136) : (h & 1 ? 6520 : 5944))];
                    vii_zz += (ai2 * (ai2 * (vgx[(h & 2 ? (h & 1 ? 2968 : 2488) : (h & 1 ? 2776 : 2392))] + zjzi * vgx[(h & 2 ? (h & 1 ? 2936 : 2456) : (h & 1 ? 2744 : 2360))]) - 5.0 * vgx[(h & 2 ? (h & 1 ? 2928 : 2448) : (h & 1 ? 2736 : 2352))]) + 2.0 * vgx[(h & 2 ? (h & 1 ? 2912 : 2432) : (h & 1 ? 2720 : 2336))]) * S;
                    vjj_zz += (aj2 * (aj2 * (vgx[(h & 2 ? (h & 1 ? 2968 : 2488) : (h & 1 ? 2776 : 2392))] - zjzi * vgx[(h & 2 ? (h & 1 ? 2960 : 2480) : (h & 1 ? 2768 : 2384))]) - 3.0 * vgx[(h & 2 ? (h & 1 ? 2928 : 2448) : (h & 1 ? 2736 : 2352))])) * S;
                    vij_zz += (aj2 * (ai2 * vgx[(h & 2 ? (h & 1 ? 2968 : 2488) : (h & 1 ? 2776 : 2392))] - 2.0 * vgx[(h & 2 ? (h & 1 ? 2952 : 2472) : (h & 1 ? 2760 : 2376))]) - 1.0 * (ai2 * vgx[(h & 2 ? (h & 1 ? 2904 : 2424) : (h & 1 ? 2712 : 2328))] - 2.0 * vgx[(h & 2 ? (h & 1 ? 2888 : 2408) : (h & 1 ? 2696 : 2312))])) * S;
                    vkk_zz += (ak2 * (ak2 * (vgx[(h & 2 ? (h & 1 ? 3408 : 2928) : (h & 1 ? 3216 : 2832))] + zlzk * vgx[(h & 2 ? (h & 1 ? 3024 : 2544) : (h & 1 ? 2832 : 2448))]) - (h & 2 ? (h & 1 ? 5.0 : 3.0) : 1.0) * vgx[(h & 2 ? (h & 1 ? 2928 : 2448) : (h & 1 ? 2736 : 2352))]) + (h & 2 ? (h & 1 ? 2.0 : 0.0) : 0.0) * vgx[(h & 2 ? (h & 1 ? 2736 : 2448) : (h & 1 ? 2736 : 2352))]) * S;
                    vll_zz += (al2 * (al2 * (vgx[(h & 2 ? (h & 1 ? 3408 : 2928) : (h & 1 ? 3216 : 2832))] - zlzk * vgx[(h & 2 ? (h & 1 ? 3312 : 2832) : (h & 1 ? 3120 : 2736))]) - (h & 2 ? (h & 1 ? 3.0 : 1.0) : (h & 1 ? 3.0 : 1.0)) * vgx[(h & 2 ? (h & 1 ? 2928 : 2448) : (h & 1 ? 2736 : 2352))])) * S;
                    vkl_zz += (al2 * (ak2 * vgx[(h & 2 ? (h & 1 ? 3408 : 2928) : (h & 1 ? 3216 : 2832))] - (h & 2 ? (h & 1 ? 2.0 : 1.0) : 0.0) * vgx[(h & 2 ? (h & 1 ? 3216 : 2736) : (h & 1 ? 2736 : 2352))]) - (h & 2 ? (h & 1 ? 1.0 : 0.0) : (h & 1 ? 1.0 : 0.0)) * (ak2 * vgx[(h & 2 ? (h & 1 ? 2640 : 2448) : (h & 1 ? 2448 : 2352))] - (h & 2 ? (h & 1 ? 2.0 : 1.0) : 0.0) * vgx[(h & 2 ? 2448 : (h & 1 ? 2736 : 2352))])) * S;
                    vij_zx += Ai * T1;
                    vij_xz += Aj * T0;
                    vjj_xz += Aj * T1;
                    vii_xz += Ai * T0;
                    vkl_zx += Ak * T3;
                    vkl_xz += Al * T2;
                    vll_xz += Al * T3;
