                }
                rys_roots_for_k(nroots, theta, rr, rw, jk.omega, jk.lr_factor, jk.sr_factor, nsq_per_block, 32, gout_id);
                for (int irys = 0; irys < nroots; ++irys) {
                    __syncthreads();
                    double s0, s1, s2;
                    double rt = rw[irys*16];
                    double rt_aa = rt / (aij + akl);
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5/aij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    double b01 = .5/akl * (1 - rt_akl);
                    for (int n = gout_id; n < 3; n += 32) {
                        if (n == 2) {
                            gx[1152] = rw[irys*16+8];
                        }
                        double *_gx = gx + n * 576;
                        double xjxi = rjri[n];
                        double Rpa = xjxi * aj_aij;
                        double c0x = Rpa - rt_aij * Rpq[n*8];
                        s0 = _gx[0];
                        s1 = c0x * s0;
                        _gx[8] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[16] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[24] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 3 * b10 * s0;
                        _gx[32] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 4 * b10 * s0;
                        _gx[40] = s2;
                        double xlxk = rlrk[n*8];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*8];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[96] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        _gx[192] = s2;
