                    vil_zz += (al2 * (ai2 * (vgx[(h & 1 ? 1904 : 2032)] - zlzk * vgx[(h & 1 ? 1712 : 1840)]) - 2.0 * (vgx[(h & 1 ? 1872 : 2000)] - zlzk * vgx[(h & 1 ? 1680 : 1808)]))) * S;
                    vjl_zz += (al2 * (aj2 * (vgx[(h & 1 ? 1904 : 2032)] - zjzi * vgx[(h & 1 ? 1888 : 2016)] - zlzk * (vgx[(h & 1 ? 1712 : 1840)] - zjzi * vgx[(h & 1 ? 1696 : 1824)])) - (h & 1 ? 2.0 : 1.0) * (vgx[(h & 1 ? 1824 : 1952)] - zlzk * vgx[(h & 1 ? 1632 : 1760)]))) * S;
                    vik_zx += Ai * T2;
                    vik_xz += Ak * T0;
                    vjk_zx += Aj * T2;
                    vjk_xz += Ak * T1;
                    vil_zx += Ai * T3;
                    vil_xz += Al * T0;
                    vjl_zx += Aj * T3;
                    vjl_xz += Al * T1;
                    w = dd_cache[(h & 1 ? 1712 : 2768)] * vgx[(h & 1 ? 768 : 1024)];
                    S = w * vgx[(h & 1 ? 192 : 0)];
                    T0 = vgx[(h & 1 ? 2880 : 2304)] * w;
                    T1 = vgx[(h & 1 ? 2896 : 2320)] * w;
                    T2 = vgx[(h & 1 ? 2912 : 2336)] * w;
                    T3 = vgx[(h & 1 ? 2928 : 2352)] * w;
                    Ai = vgx[(h & 1 ? 6848 : 6656)];
                    Aj = vgx[(h & 1 ? 6864 : 6672)];
                    Ak = vgx[(h & 1 ? 6880 : 6688)];
                    Al = vgx[(h & 1 ? 6896 : 6704)];
                    vik_zz += (ak2 * (ai2 * vgx[(h & 1 ? 2096 : 2032)] - 2.0 * vgx[(h & 1 ? 2064 : 2000)]) - 1.0 * (ai2 * vgx[(h & 1 ? 1712 : 1648)] - 2.0 * vgx[(h & 1 ? 1680 : 1616)])) * S;
                    vjk_zz += (ak2 * (aj2 * (vgx[(h & 1 ? 2096 : 2032)] - zjzi * vgx[(h & 1 ? 2080 : 2016)]) - (h & 1 ? 2.0 : 1.0) * vgx[(h & 1 ? 2016 : 1952)]) - 1.0 * (aj2 * (vgx[(h & 1 ? 1712 : 1648)] - zjzi * vgx[(h & 1 ? 1696 : 1632)]) - (h & 1 ? 2.0 : 1.0) * vgx[(h & 1 ? 1632 : 1568)])) * S;
                    vil_zz += (al2 * (ai2 * (vgx[(h & 1 ? 2096 : 2032)] - zlzk * vgx[(h & 1 ? 1904 : 1840)]) - 2.0 * (vgx[(h & 1 ? 2064 : 2000)] - zlzk * vgx[(h & 1 ? 1872 : 1808)]))) * S;
                    vjl_zz += (al2 * (aj2 * (vgx[(h & 1 ? 2096 : 2032)] - zjzi * vgx[(h & 1 ? 2080 : 2016)] - zlzk * (vgx[(h & 1 ? 1904 : 1840)] - zjzi * vgx[(h & 1 ? 1888 : 1824)])) - (h & 1 ? 2.0 : 1.0) * (vgx[(h & 1 ? 2016 : 1952)] - zlzk * vgx[(h & 1 ? 1824 : 1760)]))) * S;
                    vik_zx += Ai * T2;
                    vik_xz += Ak * T0;
                    vjk_zx += Aj * T2;
                    vjk_xz += Ak * T1;
                    vil_zx += Ai * T3;
                    vil_xz += Al * T0;
                    vjl_zx += Aj * T3;
                    vjl_xz += Al * T1;
                    w = dd_cache[(h & 1 ? 2864 : 3152)] * vgx[(h & 1 ? 960 : 768)];
                    S = w * vgx[(h & 1 ? 0 : 64)];
                    T0 = vgx[(h & 1 ? 2304 : 2496)] * w;
                    T1 = vgx[(h & 1 ? 2320 : 2512)] * w;
                    T2 = vgx[(h & 1 ? 2336 : 2528)] * w;
                    T3 = vgx[(h & 1 ? 2352 : 2544)] * w;
                    Ai = vgx[(h & 1 ? 6848 : 7232)];
                    Aj = vgx[(h & 1 ? 6864 : 7248)];
                    Ak = vgx[(h & 1 ? 6880 : 7264)];
                    Al = vgx[(h & 1 ? 6896 : 7280)];
                    vik_zz += (ak2 * (ai2 * vgx[(h & 1 ? 2096 : 2224)] - 2.0 * vgx[(h & 1 ? 2064 : 2192)]) - (h & 1 ? 1.0 : 2.0) * (ai2 * vgx[(h & 1 ? 1712 : 1840)] - 2.0 * vgx[(h & 1 ? 1680 : 1808)])) * S;
                    vjk_zz += (ak2 * (aj2 * (vgx[(h & 1 ? 2096 : 2224)] - zjzi * vgx[(h & 1 ? 2080 : 2208)]) - (h & 1 ? 2.0 : 1.0) * vgx[(h & 1 ? 2016 : 2144)]) - (h & 1 ? 1.0 : 2.0) * (aj2 * (vgx[(h & 1 ? 1712 : 1840)] - zjzi * vgx[(h & 1 ? 1696 : 1824)]) - (h & 1 ? 2.0 : 1.0) * vgx[(h & 1 ? 1632 : 1760)])) * S;
                    vil_zz += (al2 * (ai2 * (vgx[(h & 1 ? 2096 : 2224)] - zlzk * vgx[(h & 1 ? 1904 : 2032)]) - 2.0 * (vgx[(h & 1 ? 2064 : 2192)] - zlzk * vgx[(h & 1 ? 1872 : 2000)]))) * S;
                    vjl_zz += (al2 * (aj2 * (vgx[(h & 1 ? 2096 : 2224)] - zjzi * vgx[(h & 1 ? 2080 : 2208)] - zlzk * (vgx[(h & 1 ? 1904 : 2032)] - zjzi * vgx[(h & 1 ? 1888 : 2016)])) - (h & 1 ? 2.0 : 1.0) * (vgx[(h & 1 ? 2016 : 2144)] - zlzk * vgx[(h & 1 ? 1824 : 1952)]))) * S;
                    vik_zx += Ai * T2;
                    vik_xz += Ak * T0;
                    vjk_zx += Aj * T2;
                    vjk_xz += Ak * T1;
                    vil_zx += Ai * T3;
                    vil_xz += Al * T0;
                    vjl_zx += Aj * T3;
                    vjl_xz += Al * T1;
                    w = dd_cache[(h & 1 ? 3440 : 3344)] * vgx[(h & 1 ? 768 : 832)];
                    S = w * vgx[0];
                    T0 = vgx[2304] * w;
                    T1 = vgx[2320] * w;
                    T2 = vgx[2336] * w;
                    T3 = vgx[2352] * w;
                    Ai = vgx[(h & 1 ? 7424 : 7232)];
                    Aj = vgx[(h & 1 ? 7440 : 7248)];
                    Ak = vgx[(h & 1 ? 7456 : 7264)];
                    Al = vgx[(h & 1 ? 7472 : 7280)];
                    vik_zz += (ak2 * (ai2 * vgx[(h & 1 ? 2288 : 2224)] - 2.0 * vgx[(h & 1 ? 2256 : 2192)]) - 2.0 * (ai2 * vgx[(h & 1 ? 1904 : 1840)] - 2.0 * vgx[(h & 1 ? 1872 : 1808)])) * S;
                    vjk_zz += (ak2 * (aj2 * (vgx[(h & 1 ? 2288 : 2224)] - zjzi * vgx[(h & 1 ? 2272 : 2208)]) - (h & 1 ? 2.0 : 1.0) * vgx[(h & 1 ? 2208 : 2144)]) - 2.0 * (aj2 * (vgx[(h & 1 ? 1904 : 1840)] - zjzi * vgx[(h & 1 ? 1888 : 1824)]) - (h & 1 ? 2.0 : 1.0) * vgx[(h & 1 ? 1824 : 1760)])) * S;
                    vil_zz += (al2 * (ai2 * (vgx[(h & 1 ? 2288 : 2224)] - zlzk * vgx[(h & 1 ? 2096 : 2032)]) - 2.0 * (vgx[(h & 1 ? 2256 : 2192)] - zlzk * vgx[(h & 1 ? 2064 : 2000)]))) * S;
                    vjl_zz += (al2 * (aj2 * (vgx[(h & 1 ? 2288 : 2224)] - zjzi * vgx[(h & 1 ? 2272 : 2208)] - zlzk * (vgx[(h & 1 ? 2096 : 2032)] - zjzi * vgx[(h & 1 ? 2080 : 2016)])) - (h & 1 ? 2.0 : 1.0) * (vgx[(h & 1 ? 2208 : 2144)] - zlzk * vgx[(h & 1 ? 2016 : 1952)]))) * S;
                    vik_zx += Ai * T2;
                    vik_xz += Ak * T0;
                    vjk_zx += Aj * T2;
                    vjk_xz += Ak * T1;
                    vil_zx += Ai * T3;
                    vil_xz += Al * T0;
                    vjl_zx += Aj * T3;
                    vjl_xz += Al * T1;
                    break;
                    }
                }
            }
        }
        if (task_id >= ntasks) {
            break;
        }
        int ia = bas[ish*BAS_SLOTS+ATOM_OF];
        int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
        int ka = bas[ksh*BAS_SLOTS+ATOM_OF];
        int la = bas[lsh*BAS_SLOTS+ATOM_OF];
        int natm = envs.natm;
        double *ejk = jk.ejk;
        atomicAdd(ejk + (ia*natm+ka)*9 + 0, vik_xx);
        atomicAdd(ejk + (ia*natm+ka)*9 + 1, vik_xy);
        atomicAdd(ejk + (ia*natm+ka)*9 + 2, vik_xz);
        atomicAdd(ejk + (ia*natm+ka)*9 + 3, vik_yx);
        atomicAdd(ejk + (ia*natm+ka)*9 + 4, vik_yy);
        atomicAdd(ejk + (ia*natm+ka)*9 + 5, vik_yz);
        atomicAdd(ejk + (ia*natm+ka)*9 + 6, vik_zx);
        atomicAdd(ejk + (ia*natm+ka)*9 + 7, vik_zy);
        atomicAdd(ejk + (ia*natm+ka)*9 + 8, vik_zz);
        atomicAdd(ejk + (ja*natm+ka)*9 + 0, vjk_xx);
        atomicAdd(ejk + (ja*natm+ka)*9 + 1, vjk_xy);
        atomicAdd(ejk + (ja*natm+ka)*9 + 2, vjk_xz);
        atomicAdd(ejk + (ja*natm+ka)*9 + 3, vjk_yx);
        atomicAdd(ejk + (ja*natm+ka)*9 + 4, vjk_yy);
        atomicAdd(ejk + (ja*natm+ka)*9 + 5, vjk_yz);
        atomicAdd(ejk + (ja*natm+ka)*9 + 6, vjk_zx);
        atomicAdd(ejk + (ja*natm+ka)*9 + 7, vjk_zy);
        atomicAdd(ejk + (ja*natm+ka)*9 + 8, vjk_zz);
        atomicAdd(ejk + (ia*natm+la)*9 + 0, vil_xx);
        atomicAdd(ejk + (ia*natm+la)*9 + 1, vil_xy);
        atomicAdd(ejk + (ia*natm+la)*9 + 2, vil_xz);
        atomicAdd(ejk + (ia*natm+la)*9 + 3, vil_yx);
        atomicAdd(ejk + (ia*natm+la)*9 + 4, vil_yy);
        atomicAdd(ejk + (ia*natm+la)*9 + 5, vil_yz);
        atomicAdd(ejk + (ia*natm+la)*9 + 6, vil_zx);
        atomicAdd(ejk + (ia*natm+la)*9 + 7, vil_zy);
        atomicAdd(ejk + (ia*natm+la)*9 + 8, vil_zz);
        atomicAdd(ejk + (ja*natm+la)*9 + 0, vjl_xx);
        atomicAdd(ejk + (ja*natm+la)*9 + 1, vjl_xy);
        atomicAdd(ejk + (ja*natm+la)*9 + 2, vjl_xz);
        atomicAdd(ejk + (ja*natm+la)*9 + 3, vjl_yx);
        atomicAdd(ejk + (ja*natm+la)*9 + 4, vjl_yy);
        atomicAdd(ejk + (ja*natm+la)*9 + 5, vjl_yz);
        atomicAdd(ejk + (ja*natm+la)*9 + 6, vjl_zx);
        atomicAdd(ejk + (ja*natm+la)*9 + 7, vjl_zy);
        atomicAdd(ejk + (ja*natm+la)*9 + 8, vjl_zz);
    }
}
}

// type3 (dp|ds): 108 outputs, 18 tuples per direction, 16 threads x 16 quartets per block, g_size 32
__global__ static
__launch_bounds__(256, 1)
void rys_ejk_ip2_type3_gen_2120(JKENERGY_KERNEL_ARGS)
{
    JKENERGY_KERNEL_SETUP();
    constexpr int nsq_per_block = 16;
    constexpr int gout_stride = 16;
    int t_id = gout_id * nsq_per_block + sq_id;
    int threads = nsq_per_block * gout_stride;
    int nbas = envs.nbas;
    int *bas = envs.bas;
    double *env = envs.env;
    int iprim = bounds.iprim;
    int jprim = bounds.jprim;
    int kprim = bounds.kprim;
    int lprim = bounds.lprim;
    int nroots = bounds.nroots;
    double *rlrk = shared_memory + sq_id;
    double *Rpq = shared_memory + nsq_per_block * 3 + sq_id;
    // the g arrays of the three directions, then the first-derivative factors of every tuple
    double *gx = shared_memory + nsq_per_block * 6 + sq_id;
    double *rw = shared_memory + nsq_per_block * 318 + sq_id;
    double *cicj_cache = shared_memory + nsq_per_block * (318+nroots*2);

    uint32_t *bas_kl_idx = pool + worker_id * QUEUE_DEPTH;
    double *dd_cache = dd_pool + worker_id * 1744 + sq_id;
while (1) {
    __syncthreads();
    if (t_id == 0) {
        int task_id = atomicAdd(head, 1);
        int batch_kl = task_id / bounds.npairs_ij;
        pair_ij = task_id - bounds.npairs_ij * batch_kl;
        pair_kl0 = batch_kl * (QUEUE_DEPTH - 512);
        uint32_t bas_ij = bounds.pair_ij_mapping[pair_ij];
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    if (pair_kl0 >= bounds.npairs_kl) {
        break;
    }
    if (jk.lr_factor != 0) {
        _fill_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                        q_cond_ij, q_cond_kl,
                        (int *)shared_memory, jk, envs, bounds);
    } else {
        _fill_sr_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                           q_cond_ij, q_cond_kl,
                           s_cond_ij, s_cond_kl, diffuse_exps,
                           (int *)shared_memory, jk, envs, bounds);
    }
    if (ntasks == 0) {
        continue;
    }
    if (t_id == 0) {
        expi = bas[ish*BAS_SLOTS+PTR_EXP];
        expj = bas[jsh*BAS_SLOTS+PTR_EXP];
    }
    __syncthreads();
    if (t_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[t_id] = env[ri_ptr+t_id];
        rjri[t_id] = env[rj_ptr+t_id] - ri[t_id];
    }
    __syncthreads();
    double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
    double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
    double xjxi = rjri[0];
    double yjyi = rjri[1];
    double zjzi = rjri[2];
    for (int ij = t_id; ij < iprim*jprim; ij += threads) {
        int ip = ij / jprim;
        int jp = ij % jprim;
        double ai = env[expi+ip];
        double aj = env[expj+jp];
        double aij = ai + aj;
        double theta_ij = ai * aj / aij;
        double rr_ij = xjxi*xjxi + yjyi*yjyi + zjzi*zjzi;
        double Kab = exp(-theta_ij * rr_ij);
        cicj_cache[ij] = ci[ip] * cj[jp] * Kab;
    }
    __syncthreads();

    int *ao_loc = envs.ao_loc;
    int nao = ao_loc[nbas];
    double *dm = jk.dm;

    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += nsq_per_block) {
        // another thread of this quartet may still read the previous task's dd_cache
        __syncthreads();
        uint32_t bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (ish*nbas+jsh == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        int i0 = ao_loc[ish];
        int j0 = ao_loc[jsh];
        int k0 = ao_loc[ksh];
        int l0 = ao_loc[lsh];
        int expk = bas[ksh*BAS_SLOTS+PTR_EXP];
        int expl = bas[lsh*BAS_SLOTS+PTR_EXP];
        int ck = bas[ksh*BAS_SLOTS+PTR_COEFF];
        int cl = bas[lsh*BAS_SLOTS+PTR_COEFF];
        int rk = bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        int rl = bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        double xlxk = env[rl+0] - env[rk+0];
        double ylyk = env[rl+1] - env[rk+1];
        double zlzk = env[rl+2] - env[rk+2];
        if (gout_id == 0) {
            rlrk[0] = xlxk;
            rlrk[16] = ylyk;
            rlrk[2*16] = zlzk;
        }
        double vik_xx = 0;
        double vik_xy = 0;
        double vik_xz = 0;
        double vik_yx = 0;
        double vik_yy = 0;
        double vik_yz = 0;
        double vik_zx = 0;
        double vik_zy = 0;
        double vik_zz = 0;
        double vjk_xx = 0;
        double vjk_xy = 0;
        double vjk_xz = 0;
        double vjk_yx = 0;
        double vjk_yy = 0;
        double vjk_yz = 0;
        double vjk_zx = 0;
        double vjk_zy = 0;
        double vjk_zz = 0;
        double vil_xx = 0;
        double vil_xy = 0;
        double vil_xz = 0;
        double vil_yx = 0;
        double vil_yy = 0;
        double vil_yz = 0;
        double vil_zx = 0;
        double vil_zy = 0;
        double vil_zz = 0;
        double vjl_xx = 0;
        double vjl_xy = 0;
        double vjl_xz = 0;
        double vjl_yx = 0;
        double vjl_yy = 0;
        double vjl_yz = 0;
        double vjl_zx = 0;
        double vjl_zy = 0;
        double vjl_zz = 0;
        int do_j = jk.j_factor != 0.;
        int do_k = jk.k_factor != 0.;
        if (jk.n_dm == 1) {
            for (int n = gout_id; n < 108; n+=16) {
                int i = n % 6;
                int j = n / 6 % 3;
                int k = n / 18 % 6;
                int l = n / 108;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _il = _i*nao+_l;
                int _ik = _i*nao+_k;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += jk.k_factor * (dm[_jk] * dm[_il] + dm[_jl] * dm[_ik]);
                }
                if (do_j) {
                    dd += jk.j_factor * dm[_ji] * dm[_lk];
                }
                dd_cache[n*16] = fac_sym * dd;
            }
        } else {
            double *dmb = dm + nao * nao;
            for (int n = gout_id; n < 108; n+=16) {
                int i = n % 6;
                int j = n / 6 % 3;
                int k = n / 18 % 6;
                int l = n / 108;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _il = _i*nao+_l;
                int _ik = _i*nao+_k;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += dm [_jk] * dm [_il] + dm [_jl] * dm [_ik];
                    dd += dmb[_jk] * dmb[_il] + dmb[_jl] * dmb[_ik];
                    dd *= jk.k_factor;
                }
                if (do_j) {
                    dd += jk.j_factor * (dm[_ji] + dmb[_ji]) * (dm[_lk] + dmb[_lk]);
                }
                dd_cache[n*16] = fac_sym * dd;
            }
        }
        if (gout_id == 0) {
            dd_cache[1728] = 0;
        }
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            int kp = klp / lprim;
            int lp = klp % lprim;
            double ak = env[expk+kp];
            double al = env[expl+lp];
            double ak2 = ak * 2;
            double al2 = al * 2;
            double akl = ak + al;
            double al_akl = al / akl;
            double theta_kl = ak * al_akl;
            __syncthreads();
            if (gout_id == 0) {
                double Kcd = exp(-theta_kl * (xlxk*xlxk+ylyk*ylyk+zlzk*zlzk));
                double ckcl = env[ck+kp] * env[cl+lp] * Kcd;
                gx[0] = ckcl;
            }
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                if (fabs(cicj_cache[ijp]) < PRIM_CUTOFF) continue;
                int ip = ijp / jprim;
                int jp = ijp % jprim;
                double ai = env[expi+ip];
                double aj = env[expj+jp];
                double ai2 = ai * 2;
                double aj2 = aj * 2;
                double aij = ai + aj;
                double aj_aij = aj / aij;
                double xij = ri[0] + rjri[0] * aj_aij;
                double yij = ri[1] + rjri[1] * aj_aij;
                double zij = ri[2] + rjri[2] * aj_aij;
                double xkl = env[rk+0] + xlxk * al_akl;
                double ykl = env[rk+1] + ylyk * al_akl;
                double zkl = env[rk+2] + zlzk * al_akl;
                double xpq = xij - xkl;
                double ypq = yij - ykl;
                double zpq = zij - zkl;
                double theta = aij * akl / (aij + akl);
                double rr = xpq * xpq + ypq * ypq + zpq * zpq;
                __syncthreads();
                if (gout_id == 0) {
                    Rpq[0] = xpq;
                    Rpq[16] = ypq;
                    Rpq[2*16] = zpq;
                    double cicj = cicj_cache[ijp];
                    gx[32*16] = cicj / (aij*akl*sqrt(aij+akl));
                }
                rys_roots_for_k(nroots, theta, rr, rw, jk.omega, jk.lr_factor, jk.sr_factor, nsq_per_block, 16, gout_id);
                for (int irys = 0; irys < nroots; ++irys) {
                    __syncthreads();
                    double s0, s1, s2;
                    double rt = rw[irys*32];
                    double rt_aa = rt / (aij + akl);
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5/aij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    double b01 = .5/akl * (1 - rt_akl);
                    for (int n = gout_id; n < 3; n += 16) {
                        if (n == 2) {
                            gx[1024] = rw[irys*32+16];
                        }
