                    vii_yy += (ai2 * (ai2 * (vgx[(h & 1 ? 1104 : 1264)] + yjyi * vgx[(h & 1 ? 1040 : 1200)]) - (h & 1 ? 1.0 : 5.0) * vgx[(h & 1 ? 1024 : 1184)]) + (h & 1 ? 0.0 : 2.0) * vgx[(h & 1 ? 1024 : 1152)]) * S;
                    vjj_yy += (aj2 * (aj2 * (vgx[(h & 1 ? 1104 : 1264)] - yjyi * vgx[(h & 1 ? 1088 : 1248)]) - (h & 1 ? 1.0 : 5.0) * vgx[(h & 1 ? 1024 : 1184)]) + (h & 1 ? 0.0 : 2.0) * vgx[(h & 1 ? 1024 : 1056)]) * S;
                    vij_yy += (aj2 * (ai2 * vgx[(h & 1 ? 1104 : 1264)] - (h & 1 ? 0.0 : 2.0) * vgx[(h & 1 ? 1024 : 1232)]) - (h & 1 ? 0.0 : 2.0) * (ai2 * vgx[(h & 1 ? 1024 : 1136)] - (h & 1 ? 0.0 : 2.0) * vgx[(h & 1 ? 1024 : 1104)])) * S;
                    vkk_yy += (ak2 * (ak2 * (vgx[(h & 1 ? 1792 : 1952)] + ylyk * vgx[(h & 1 ? 1280 : 1440)]) - 1.0 * vgx[(h & 1 ? 1024 : 1184)])) * S;
                    vll_yy += (al2 * (al2 * (vgx[(h & 1 ? 1792 : 1952)] - ylyk * vgx[(h & 1 ? 1536 : 1696)]) - 1.0 * vgx[(h & 1 ? 1024 : 1184)])) * S;
                    vkl_yy += (al2 * (ak2 * vgx[(h & 1 ? 1792 : 1952)])) * S;
                    vij_yz += Ai * T1;
                    vij_zy += Aj * T0;
                    vjj_yz += Aj * T1;
                    vii_yz += Ai * T0;
                    vkl_yz += Ak * T3;
                    vkl_zy += Al * T2;
                    vll_yz += Al * T3;
                    vkk_yz += Ak * T2;
                    asm volatile("mov.u32 %0, %%tid.y;" : "=r"(tid_y));
                    h = tid_y % 2;
                    w = dd_cache[(h & 1 ? 576 : 560)] * vgx[1024];
                    S = w * vgx[(h & 1 ? 160 : 0)];
                    T0 = vgx[(h & 1 ? 3584 : 3072)] * w;
                    T1 = vgx[(h & 1 ? 3600 : 3088)] * w;
                    T2 = vgx[(h & 1 ? 3616 : 3104)] * w;
                    T3 = vgx[(h & 1 ? 3632 : 3120)] * w;
                    Ai = vgx[(h & 1 ? 4224 : 4736)];
                    Aj = vgx[(h & 1 ? 4240 : 4752)];
                    Ak = vgx[(h & 1 ? 4256 : 4768)];
                    Al = vgx[(h & 1 ? 4272 : 4784)];
                    vii_zz += (ai2 * (ai2 * (vgx[(h & 1 ? 2128 : 2288)] + zjzi * vgx[(h & 1 ? 2064 : 2224)]) - (h & 1 ? 1.0 : 5.0) * vgx[(h & 1 ? 2048 : 2208)]) + (h & 1 ? 0.0 : 2.0) * vgx[(h & 1 ? 2048 : 2176)]) * S;
                    vjj_zz += (aj2 * (aj2 * (vgx[(h & 1 ? 2128 : 2288)] - zjzi * vgx[(h & 1 ? 2112 : 2272)]) - (h & 1 ? 1.0 : 5.0) * vgx[(h & 1 ? 2048 : 2208)]) + (h & 1 ? 0.0 : 2.0) * vgx[(h & 1 ? 2048 : 2080)]) * S;
                    vij_zz += (aj2 * (ai2 * vgx[(h & 1 ? 2128 : 2288)] - (h & 1 ? 0.0 : 2.0) * vgx[(h & 1 ? 2048 : 2256)]) - (h & 1 ? 0.0 : 2.0) * (ai2 * vgx[(h & 1 ? 2048 : 2160)] - (h & 1 ? 0.0 : 2.0) * vgx[(h & 1 ? 2048 : 2128)])) * S;
                    vkk_zz += (ak2 * (ak2 * (vgx[(h & 1 ? 2816 : 2976)] + zlzk * vgx[(h & 1 ? 2304 : 2464)]) - 1.0 * vgx[(h & 1 ? 2048 : 2208)])) * S;
                    vll_zz += (al2 * (al2 * (vgx[(h & 1 ? 2816 : 2976)] - zlzk * vgx[(h & 1 ? 2560 : 2720)]) - 1.0 * vgx[(h & 1 ? 2048 : 2208)])) * S;
                    vkl_zz += (al2 * (ak2 * vgx[(h & 1 ? 2816 : 2976)])) * S;
                    vij_zx += Ai * T1;
                    vij_xz += Aj * T0;
                    vjj_xz += Aj * T1;
                    vii_xz += Ai * T0;
                    vkl_zx += Ak * T3;
                    vkl_xz += Al * T2;
                    vll_xz += Al * T3;
                    vkk_xz += Ak * T2;
                    break;
                    }
                }
            }
        }
        if (task_id >= ntasks) {
            break;
        }
        int ia = bas[ish*BAS_SLOTS+ATOM_OF];
        int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
        int ka = bas[ksh*BAS_SLOTS+ATOM_OF];
        int la = bas[lsh*BAS_SLOTS+ATOM_OF];
        int natm = envs.natm;
        double *ejk = jk.ejk;
        atomicAdd(ejk + (ka*natm+la)*9 + 0, vkl_xx);
        atomicAdd(ejk + (ka*natm+la)*9 + 1, vkl_xy);
        atomicAdd(ejk + (ka*natm+la)*9 + 2, vkl_xz);
        atomicAdd(ejk + (ka*natm+la)*9 + 3, vkl_yx);
        atomicAdd(ejk + (ka*natm+la)*9 + 4, vkl_yy);
        atomicAdd(ejk + (ka*natm+la)*9 + 5, vkl_yz);
        atomicAdd(ejk + (ka*natm+la)*9 + 6, vkl_zx);
        atomicAdd(ejk + (ka*natm+la)*9 + 7, vkl_zy);
        atomicAdd(ejk + (ka*natm+la)*9 + 8, vkl_zz);
        atomicAdd(ejk + (ka*natm+ka)*9 + 0, vkk_xx*.5);
        atomicAdd(ejk + (ka*natm+ka)*9 + 3, vkk_xy);
        atomicAdd(ejk + (ka*natm+ka)*9 + 4, vkk_yy*.5);
        atomicAdd(ejk + (ka*natm+ka)*9 + 6, vkk_xz);
        atomicAdd(ejk + (ka*natm+ka)*9 + 7, vkk_yz);
        atomicAdd(ejk + (ka*natm+ka)*9 + 8, vkk_zz*.5);
        atomicAdd(ejk + (la*natm+la)*9 + 0, vll_xx*.5);
        atomicAdd(ejk + (la*natm+la)*9 + 3, vll_xy);
        atomicAdd(ejk + (la*natm+la)*9 + 4, vll_yy*.5);
        atomicAdd(ejk + (la*natm+la)*9 + 6, vll_xz);
        atomicAdd(ejk + (la*natm+la)*9 + 7, vll_yz);
        atomicAdd(ejk + (la*natm+la)*9 + 8, vll_zz*.5);
    }
    int ia = bas[ish*BAS_SLOTS+ATOM_OF];
    int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
    int natm = envs.natm;
    double *ejk = jk.ejk;
    atomicAdd(ejk + (ia*natm+ja)*9 + 0, vij_xx);
    atomicAdd(ejk + (ia*natm+ja)*9 + 1, vij_xy);
    atomicAdd(ejk + (ia*natm+ja)*9 + 2, vij_xz);
    atomicAdd(ejk + (ia*natm+ja)*9 + 3, vij_yx);
    atomicAdd(ejk + (ia*natm+ja)*9 + 4, vij_yy);
    atomicAdd(ejk + (ia*natm+ja)*9 + 5, vij_yz);
    atomicAdd(ejk + (ia*natm+ja)*9 + 6, vij_zx);
    atomicAdd(ejk + (ia*natm+ja)*9 + 7, vij_zy);
    atomicAdd(ejk + (ia*natm+ja)*9 + 8, vij_zz);
    atomicAdd(ejk + (ia*natm+ia)*9 + 0, vii_xx*.5);
    atomicAdd(ejk + (ia*natm+ia)*9 + 3, vii_xy);
    atomicAdd(ejk + (ia*natm+ia)*9 + 4, vii_yy*.5);
    atomicAdd(ejk + (ia*natm+ia)*9 + 6, vii_xz);
    atomicAdd(ejk + (ia*natm+ia)*9 + 7, vii_yz);
    atomicAdd(ejk + (ia*natm+ia)*9 + 8, vii_zz*.5);
    atomicAdd(ejk + (ja*natm+ja)*9 + 0, vjj_xx*.5);
    atomicAdd(ejk + (ja*natm+ja)*9 + 3, vjj_xy);
    atomicAdd(ejk + (ja*natm+ja)*9 + 4, vjj_yy*.5);
    atomicAdd(ejk + (ja*natm+ja)*9 + 6, vjj_xz);
    atomicAdd(ejk + (ja*natm+ja)*9 + 7, vjj_yz);
    atomicAdd(ejk + (ja*natm+ja)*9 + 8, vjj_zz*.5);
}
}

// type3 (dd|ss): 36 outputs, 9 tuples per direction, 8 threads x 32 quartets per block, g_size 24
__global__ static
__launch_bounds__(256, 1)
void rys_ejk_ip2_type3_gen_2200(JKENERGY_KERNEL_ARGS)
{
    JKENERGY_KERNEL_SETUP();
    constexpr int nsq_per_block = 32;
    constexpr int gout_stride = 8;
    int t_id = gout_id * nsq_per_block + sq_id;
    int threads = nsq_per_block * gout_stride;
    int nbas = envs.nbas;
    int *bas = envs.bas;
    double *env = envs.env;
    int iprim = bounds.iprim;
    int jprim = bounds.jprim;
    int kprim = bounds.kprim;
    int lprim = bounds.lprim;
    int nroots = bounds.nroots;
    double *rlrk = shared_memory + sq_id;
    double *Rpq = shared_memory + nsq_per_block * 3 + sq_id;
    // the g arrays of the three directions, then the first-derivative factors of every tuple
    double *gx = shared_memory + nsq_per_block * 6 + sq_id;
    double *rw = shared_memory + nsq_per_block * 186 + sq_id;
    double *cicj_cache = shared_memory + nsq_per_block * (186+nroots*2);

    uint32_t *bas_kl_idx = pool + worker_id * QUEUE_DEPTH;
    double *dd_cache = dd_pool + worker_id * 1152 + sq_id;
while (1) {
    __syncthreads();
    if (t_id == 0) {
        int task_id = atomicAdd(head, 1);
        int batch_kl = task_id / bounds.npairs_ij;
        pair_ij = task_id - bounds.npairs_ij * batch_kl;
        pair_kl0 = batch_kl * (QUEUE_DEPTH - 512);
        uint32_t bas_ij = bounds.pair_ij_mapping[pair_ij];
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    if (pair_kl0 >= bounds.npairs_kl) {
        break;
    }
    if (jk.lr_factor != 0) {
        _fill_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                        q_cond_ij, q_cond_kl,
                        (int *)shared_memory, jk, envs, bounds);
    } else {
        _fill_sr_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                           q_cond_ij, q_cond_kl,
                           s_cond_ij, s_cond_kl, diffuse_exps,
                           (int *)shared_memory, jk, envs, bounds);
    }
    if (ntasks == 0) {
        continue;
    }
    if (t_id == 0) {
        expi = bas[ish*BAS_SLOTS+PTR_EXP];
        expj = bas[jsh*BAS_SLOTS+PTR_EXP];
    }
    __syncthreads();
    if (t_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[t_id] = env[ri_ptr+t_id];
        rjri[t_id] = env[rj_ptr+t_id] - ri[t_id];
    }
    __syncthreads();
    double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
    double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
    double xjxi = rjri[0];
    double yjyi = rjri[1];
    double zjzi = rjri[2];
    for (int ij = t_id; ij < iprim*jprim; ij += threads) {
        int ip = ij / jprim;
        int jp = ij % jprim;
        double ai = env[expi+ip];
        double aj = env[expj+jp];
        double aij = ai + aj;
        double theta_ij = ai * aj / aij;
        double rr_ij = xjxi*xjxi + yjyi*yjyi + zjzi*zjzi;
        double Kab = exp(-theta_ij * rr_ij);
        cicj_cache[ij] = ci[ip] * cj[jp] * Kab;
    }
    __syncthreads();

    int *ao_loc = envs.ao_loc;
    int nao = ao_loc[nbas];
    double *dm = jk.dm;

    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += nsq_per_block) {
        // another thread of this quartet may still read the previous task's dd_cache
        __syncthreads();
        uint32_t bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (ish*nbas+jsh == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        int i0 = ao_loc[ish];
        int j0 = ao_loc[jsh];
        int k0 = ao_loc[ksh];
        int l0 = ao_loc[lsh];
        int expk = bas[ksh*BAS_SLOTS+PTR_EXP];
        int expl = bas[lsh*BAS_SLOTS+PTR_EXP];
        int ck = bas[ksh*BAS_SLOTS+PTR_COEFF];
        int cl = bas[lsh*BAS_SLOTS+PTR_COEFF];
        int rk = bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        int rl = bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        double xlxk = env[rl+0] - env[rk+0];
        double ylyk = env[rl+1] - env[rk+1];
        double zlzk = env[rl+2] - env[rk+2];
        if (gout_id == 0) {
            rlrk[0] = xlxk;
            rlrk[32] = ylyk;
            rlrk[2*32] = zlzk;
        }
        double vik_xx = 0;
        double vik_xy = 0;
        double vik_xz = 0;
        double vik_yx = 0;
        double vik_yy = 0;
        double vik_yz = 0;
        double vik_zx = 0;
        double vik_zy = 0;
        double vik_zz = 0;
        double vjk_xx = 0;
        double vjk_xy = 0;
        double vjk_xz = 0;
        double vjk_yx = 0;
        double vjk_yy = 0;
        double vjk_yz = 0;
        double vjk_zx = 0;
        double vjk_zy = 0;
        double vjk_zz = 0;
        double vil_xx = 0;
        double vil_xy = 0;
        double vil_xz = 0;
        double vil_yx = 0;
        double vil_yy = 0;
        double vil_yz = 0;
        double vil_zx = 0;
        double vil_zy = 0;
        double vil_zz = 0;
        double vjl_xx = 0;
        double vjl_xy = 0;
        double vjl_xz = 0;
        double vjl_yx = 0;
        double vjl_yy = 0;
        double vjl_yz = 0;
        double vjl_zx = 0;
        double vjl_zy = 0;
        double vjl_zz = 0;
        int do_j = jk.j_factor != 0.;
        int do_k = jk.k_factor != 0.;
        if (jk.n_dm == 1) {
            for (int n = gout_id; n < 36; n+=8) {
                int i = n % 6;
                int j = n / 6 % 6;
                int k = n / 36 % 1;
                int l = n / 36;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _il = _i*nao+_l;
                int _ik = _i*nao+_k;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += jk.k_factor * (dm[_jk] * dm[_il] + dm[_jl] * dm[_ik]);
                }
                if (do_j) {
                    dd += jk.j_factor * dm[_ji] * dm[_lk];
                }
                dd_cache[n*32] = fac_sym * dd;
            }
        } else {
            double *dmb = dm + nao * nao;
            for (int n = gout_id; n < 36; n+=8) {
                int i = n % 6;
                int j = n / 6 % 6;
                int k = n / 36 % 1;
                int l = n / 36;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _il = _i*nao+_l;
                int _ik = _i*nao+_k;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += dm [_jk] * dm [_il] + dm [_jl] * dm [_ik];
                    dd += dmb[_jk] * dmb[_il] + dmb[_jl] * dmb[_ik];
                    dd *= jk.k_factor;
                }
                if (do_j) {
                    dd += jk.j_factor * (dm[_ji] + dmb[_ji]) * (dm[_lk] + dmb[_lk]);
                }
                dd_cache[n*32] = fac_sym * dd;
            }
        }
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            int kp = klp / lprim;
            int lp = klp % lprim;
            double ak = env[expk+kp];
            double al = env[expl+lp];
            double ak2 = ak * 2;
            double al2 = al * 2;
            double akl = ak + al;
            double al_akl = al / akl;
            double theta_kl = ak * al_akl;
            __syncthreads();
            if (gout_id == 0) {
                double Kcd = exp(-theta_kl * (xlxk*xlxk+ylyk*ylyk+zlzk*zlzk));
                double ckcl = env[ck+kp] * env[cl+lp] * Kcd;
                gx[0] = ckcl;
            }
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                if (fabs(cicj_cache[ijp]) < PRIM_CUTOFF) continue;
                int ip = ijp / jprim;
                int jp = ijp % jprim;
                double ai = env[expi+ip];
                double aj = env[expj+jp];
                double ai2 = ai * 2;
                double aj2 = aj * 2;
                double aij = ai + aj;
                double aj_aij = aj / aij;
                double xij = ri[0] + rjri[0] * aj_aij;
                double yij = ri[1] + rjri[1] * aj_aij;
                double zij = ri[2] + rjri[2] * aj_aij;
                double xkl = env[rk+0] + xlxk * al_akl;
                double ykl = env[rk+1] + ylyk * al_akl;
                double zkl = env[rk+2] + zlzk * al_akl;
                double xpq = xij - xkl;
                double ypq = yij - ykl;
                double zpq = zij - zkl;
                double theta = aij * akl / (aij + akl);
                double rr = xpq * xpq + ypq * ypq + zpq * zpq;
                __syncthreads();
                if (gout_id == 0) {
                    Rpq[0] = xpq;
                    Rpq[32] = ypq;
                    Rpq[2*32] = zpq;
                    double cicj = cicj_cache[ijp];
                    gx[24*32] = cicj / (aij*akl*sqrt(aij+akl));
                }
                rys_roots_for_k(nroots, theta, rr, rw, jk.omega, jk.lr_factor, jk.sr_factor, nsq_per_block, 8, gout_id);
                for (int irys = 0; irys < nroots; ++irys) {
                    __syncthreads();
                    double s0, s1, s2;
                    double rt = rw[irys*64];
                    double rt_aa = rt / (aij + akl);
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5/aij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    for (int n = gout_id; n < 3; n += 8) {
                        if (n == 2) {
                            gx[1536] = rw[irys*64+32];
                        }
                        double *_gx = gx + n * 768;
                        double xjxi = rjri[n];
                        double Rpa = xjxi * aj_aij;
                        double c0x = Rpa - rt_aij * Rpq[n*32];
                        s0 = _gx[0];
                        s1 = c0x * s0;
                        _gx[32] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[64] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[96] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 3 * b10 * s0;
                        _gx[128] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 4 * b10 * s0;
                        _gx[160] = s2;
                        double xlxk = rlrk[n*32];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*32];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[384] = s1;
                        s0 = _gx[32];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[416] = s1;
                        s0 = _gx[64];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[32];
                        _gx[448] = s1;
                        s0 = _gx[96];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[64];
                        _gx[480] = s1;
                        s0 = _gx[128];
                        s1 = cpx * s0;
                        s1 += 4 * b00 * _gx[96];
                        _gx[512] = s1;
                        s0 = _gx[160];
                        s1 = cpx * s0;
                        s1 += 5 * b00 * _gx[128];
                        _gx[544] = s1;
                        s1 = _gx[160];
                        s0 = _gx[128];
                        _gx[256] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[96];
                        _gx[224] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[64];
                        _gx[192] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[32];
                        _gx[160] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[0];
                        _gx[128] = s1 - xjxi * s0;
                        s1 = s0;
                        s1 = _gx[256];
                        s0 = _gx[224];
                        _gx[352] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[192];
                        _gx[320] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[160];
                        _gx[288] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[128];
                        _gx[256] = s1 - xjxi * s0;
                        s1 = s0;
                        s1 = _gx[544];
                        s0 = _gx[512];
                        _gx[640] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[480];
                        _gx[608] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[448];
                        _gx[576] = s1 - xjxi * s0;
                        s1 = s0;
                        s0 = _gx[416];
                        _gx[544] = s1 - xjxi * s0;
