                    T0 = vgx[3264] * w;
                    T1 = vgx[3296] * w;
                    T2 = vgx[3328] * w;
                    T3 = vgx[3360] * w;
                    w = dd_cache[576] * vgx[1440];
                    S += w * vgx[576];
                    T0 += vgx[2752] * w;
                    T1 += vgx[2784] * w;
                    T2 += vgx[2816] * w;
                    T3 += vgx[2848] * w;
                    Ai = vgx[2112];
                    Aj = vgx[2144];
                    Ak = vgx[2176];
                    Al = vgx[2208];
                    vik_xx += (ak2 * (ai2 * vgx[256] - 1.0 * vgx[192]) - 1.0 * (ai2 * vgx[64] - 1.0 * vgx[0])) * S;
                    vjk_xx += (ak2 * (aj2 * (vgx[256] - xjxi * vgx[224])) - 1.0 * (aj2 * (vgx[64] - xjxi * vgx[32]))) * S;
                    vil_xx += (al2 * (ai2 * (vgx[256] - xlxk * vgx[160]) - 1.0 * (vgx[192] - xlxk * vgx[96]))) * S;
                    vjl_xx += (al2 * (aj2 * (vgx[256] - xjxi * vgx[224] - xlxk * (vgx[160] - xjxi * vgx[128])))) * S;
                    vik_xy += Ai * T2;
                    vik_yx += Ak * T0;
                    vjk_xy += Aj * T2;
                    vjk_yx += Ak * T1;
                    vil_xy += Ai * T3;
                    vil_yx += Al * T0;
                    vjl_xy += Aj * T3;
                    vjl_yx += Al * T1;
                    w = dd_cache[128] * vgx[288];
                    S = w * vgx[1152];
                    T0 = vgx[3776] * w;
                    T1 = vgx[3808] * w;
                    T2 = vgx[3840] * w;
                    T3 = vgx[3872] * w;
                    w = dd_cache[704] * vgx[0];
                    S += w * vgx[1440];
                    T0 += vgx[4288] * w;
                    T1 += vgx[4320] * w;
                    T2 += vgx[4352] * w;
                    T3 += vgx[4384] * w;
                    Ai = vgx[3136];
                    Aj = vgx[3168];
                    Ak = vgx[3200];
                    Al = vgx[3232];
                    vik_yy += (ak2 * (ai2 * vgx[832] - 1.0 * vgx[768]) - 1.0 * (ai2 * vgx[640] - 1.0 * vgx[576])) * S;
                    vjk_yy += (ak2 * (aj2 * (vgx[832] - yjyi * vgx[800])) - 1.0 * (aj2 * (vgx[640] - yjyi * vgx[608]))) * S;
                    vil_yy += (al2 * (ai2 * (vgx[832] - ylyk * vgx[736]) - 1.0 * (vgx[768] - ylyk * vgx[672]))) * S;
                    vjl_yy += (al2 * (aj2 * (vgx[832] - yjyi * vgx[800] - ylyk * (vgx[736] - yjyi * vgx[704])))) * S;
                    vik_yz += Ai * T2;
                    vik_zy += Ak * T0;
                    vjk_yz += Aj * T2;
                    vjk_zy += Ak * T1;
                    vil_yz += Ai * T3;
                    vil_zy += Al * T0;
                    vjl_yz += Aj * T3;
                    vjl_zy += Al * T1;
                    w = dd_cache[256] * vgx[576];
                    S = w * vgx[288];
                    T0 = vgx[2240] * w;
                    T1 = vgx[2272] * w;
                    T2 = vgx[2304] * w;
                    T3 = vgx[2336] * w;
                    w = dd_cache[544] * vgx[864];
                    S += w * vgx[0];
                    T0 += vgx[1728] * w;
                    T1 += vgx[1760] * w;
                    T2 += vgx[1792] * w;
                    T3 += vgx[1824] * w;
                    Ai = vgx[4160];
                    Aj = vgx[4192];
                    Ak = vgx[4224];
                    Al = vgx[4256];
                    vik_zz += (ak2 * (ai2 * vgx[1408] - 1.0 * vgx[1344]) - 1.0 * (ai2 * vgx[1216] - 1.0 * vgx[1152])) * S;
                    vjk_zz += (ak2 * (aj2 * (vgx[1408] - zjzi * vgx[1376])) - 1.0 * (aj2 * (vgx[1216] - zjzi * vgx[1184]))) * S;
                    vil_zz += (al2 * (ai2 * (vgx[1408] - zlzk * vgx[1312]) - 1.0 * (vgx[1344] - zlzk * vgx[1248]))) * S;
                    vjl_zz += (al2 * (aj2 * (vgx[1408] - zjzi * vgx[1376] - zlzk * (vgx[1312] - zjzi * vgx[1280])))) * S;
                    vik_zx += Ai * T2;
                    vik_xz += Ak * T0;
                    vjk_zx += Aj * T2;
                    vjk_xz += Ak * T1;
                    vil_zx += Ai * T3;
                    vil_xz += Al * T0;
                    vjl_zx += Aj * T3;
                    vjl_xz += Al * T1;
                    break;
                    case 7:
                    w = dd_cache[0] * vgx[1152];
                    S = w * vgx[576];
                    T0 = vgx[2752] * w;
                    T1 = vgx[2784] * w;
                    T2 = vgx[2816] * w;
                    T3 = vgx[2848] * w;
                    Ai = vgx[2624];
                    Aj = vgx[2656];
                    Ak = vgx[2688];
                    Al = vgx[2720];
                    vik_xx += (ak2 * (ai2 * vgx[544] - 1.0 * vgx[480]) - 1.0 * (ai2 * vgx[352] - 1.0 * vgx[288])) * S;
                    vjk_xx += (ak2 * (aj2 * (vgx[544] - xjxi * vgx[512])) - 1.0 * (aj2 * (vgx[352] - xjxi * vgx[320]))) * S;
                    vil_xx += (al2 * (ai2 * (vgx[544] - xlxk * vgx[448]) - 1.0 * (vgx[480] - xlxk * vgx[384])) - 1.0 * (ai2 * vgx[160] - 1.0 * vgx[96])) * S;
                    vjl_xx += (al2 * (aj2 * (vgx[544] - xjxi * vgx[512] - xlxk * (vgx[448] - xjxi * vgx[416]))) - 1.0 * (aj2 * (vgx[160] - xjxi * vgx[128]))) * S;
                    vik_xy += Ai * T2;
                    vik_yx += Ak * T0;
                    vjk_xy += Aj * T2;
                    vjk_yx += Ak * T1;
                    vil_xy += Ai * T3;
                    vil_yx += Al * T0;
                    vjl_xy += Aj * T3;
                    vjl_yx += Al * T1;
                    w = dd_cache[416] * vgx[0];
                    S = w * vgx[1152];
                    T0 = vgx[3776] * w;
                    T1 = vgx[3808] * w;
                    T2 = vgx[3840] * w;
                    T3 = vgx[3872] * w;
                    Ai = vgx[3648];
                    Aj = vgx[3680];
                    Ak = vgx[3712];
                    Al = vgx[3744];
                    vik_yy += (ak2 * (ai2 * vgx[1120] - 1.0 * vgx[1056]) - 1.0 * (ai2 * vgx[928] - 1.0 * vgx[864])) * S;
                    vjk_yy += (ak2 * (aj2 * (vgx[1120] - yjyi * vgx[1088])) - 1.0 * (aj2 * (vgx[928] - yjyi * vgx[896]))) * S;
                    vil_yy += (al2 * (ai2 * (vgx[1120] - ylyk * vgx[1024]) - 1.0 * (vgx[1056] - ylyk * vgx[960])) - 1.0 * (ai2 * vgx[736] - 1.0 * vgx[672])) * S;
                    vjl_yy += (al2 * (aj2 * (vgx[1120] - yjyi * vgx[1088] - ylyk * (vgx[1024] - yjyi * vgx[992]))) - 1.0 * (aj2 * (vgx[736] - yjyi * vgx[704]))) * S;
                    vik_yz += Ai * T2;
                    vik_zy += Ak * T0;
                    vjk_yz += Aj * T2;
                    vjk_zy += Ak * T1;
                    vil_yz += Ai * T3;
                    vil_zy += Al * T0;
                    vjl_yz += Aj * T3;
                    vjl_zy += Al * T1;
                    w = dd_cache[832] * vgx[576];
                    S = w * vgx[0];
                    T0 = vgx[1728] * w;
                    T1 = vgx[1760] * w;
                    T2 = vgx[1792] * w;
                    T3 = vgx[1824] * w;
                    Ai = vgx[4672];
                    Aj = vgx[4704];
                    Ak = vgx[4736];
                    Al = vgx[4768];
                    vik_zz += (ak2 * (ai2 * vgx[1696] - 1.0 * vgx[1632]) - 1.0 * (ai2 * vgx[1504] - 1.0 * vgx[1440])) * S;
                    vjk_zz += (ak2 * (aj2 * (vgx[1696] - zjzi * vgx[1664])) - 1.0 * (aj2 * (vgx[1504] - zjzi * vgx[1472]))) * S;
                    vil_zz += (al2 * (ai2 * (vgx[1696] - zlzk * vgx[1600]) - 1.0 * (vgx[1632] - zlzk * vgx[1536])) - 1.0 * (ai2 * vgx[1312] - 1.0 * vgx[1248])) * S;
                    vjl_zz += (al2 * (aj2 * (vgx[1696] - zjzi * vgx[1664] - zlzk * (vgx[1600] - zjzi * vgx[1568]))) - 1.0 * (aj2 * (vgx[1312] - zjzi * vgx[1280]))) * S;
                    vik_zx += Ai * T2;
                    vik_xz += Ak * T0;
                    vjk_zx += Aj * T2;
                    vjk_xz += Ak * T1;
                    vil_zx += Ai * T3;
                    vil_xz += Al * T0;
                    vjl_zx += Aj * T3;
                    vjl_xz += Al * T1;
                    break;
                    }
                }
            }
        }
        if (task_id >= ntasks) {
            break;
        }
        int ia = bas[ish*BAS_SLOTS+ATOM_OF];
        int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
        int ka = bas[ksh*BAS_SLOTS+ATOM_OF];
        int la = bas[lsh*BAS_SLOTS+ATOM_OF];
        int natm = envs.natm;
        double *ejk = jk.ejk;
        atomicAdd(ejk + (ia*natm+ka)*9 + 0, vik_xx);
        atomicAdd(ejk + (ia*natm+ka)*9 + 1, vik_xy);
        atomicAdd(ejk + (ia*natm+ka)*9 + 2, vik_xz);
        atomicAdd(ejk + (ia*natm+ka)*9 + 3, vik_yx);
        atomicAdd(ejk + (ia*natm+ka)*9 + 4, vik_yy);
        atomicAdd(ejk + (ia*natm+ka)*9 + 5, vik_yz);
        atomicAdd(ejk + (ia*natm+ka)*9 + 6, vik_zx);
        atomicAdd(ejk + (ia*natm+ka)*9 + 7, vik_zy);
        atomicAdd(ejk + (ia*natm+ka)*9 + 8, vik_zz);
        atomicAdd(ejk + (ja*natm+ka)*9 + 0, vjk_xx);
        atomicAdd(ejk + (ja*natm+ka)*9 + 1, vjk_xy);
        atomicAdd(ejk + (ja*natm+ka)*9 + 2, vjk_xz);
        atomicAdd(ejk + (ja*natm+ka)*9 + 3, vjk_yx);
        atomicAdd(ejk + (ja*natm+ka)*9 + 4, vjk_yy);
        atomicAdd(ejk + (ja*natm+ka)*9 + 5, vjk_yz);
        atomicAdd(ejk + (ja*natm+ka)*9 + 6, vjk_zx);
        atomicAdd(ejk + (ja*natm+ka)*9 + 7, vjk_zy);
        atomicAdd(ejk + (ja*natm+ka)*9 + 8, vjk_zz);
        atomicAdd(ejk + (ia*natm+la)*9 + 0, vil_xx);
        atomicAdd(ejk + (ia*natm+la)*9 + 1, vil_xy);
        atomicAdd(ejk + (ia*natm+la)*9 + 2, vil_xz);
        atomicAdd(ejk + (ia*natm+la)*9 + 3, vil_yx);
        atomicAdd(ejk + (ia*natm+la)*9 + 4, vil_yy);
        atomicAdd(ejk + (ia*natm+la)*9 + 5, vil_yz);
        atomicAdd(ejk + (ia*natm+la)*9 + 6, vil_zx);
        atomicAdd(ejk + (ia*natm+la)*9 + 7, vil_zy);
        atomicAdd(ejk + (ia*natm+la)*9 + 8, vil_zz);
        atomicAdd(ejk + (ja*natm+la)*9 + 0, vjl_xx);
        atomicAdd(ejk + (ja*natm+la)*9 + 1, vjl_xy);
        atomicAdd(ejk + (ja*natm+la)*9 + 2, vjl_xz);
        atomicAdd(ejk + (ja*natm+la)*9 + 3, vjl_yx);
        atomicAdd(ejk + (ja*natm+la)*9 + 4, vjl_yy);
        atomicAdd(ejk + (ja*natm+la)*9 + 5, vjl_yz);
        atomicAdd(ejk + (ja*natm+la)*9 + 6, vjl_zx);
        atomicAdd(ejk + (ja*natm+la)*9 + 7, vjl_zy);
        atomicAdd(ejk + (ja*natm+la)*9 + 8, vjl_zz);
    }
}
}

// type3 (dp|ss): 18 outputs, 6 tuples per direction, 8 threads x 32 quartets per block, g_size 16
__global__ static
__launch_bounds__(256, 1)
void rys_ejk_ip2_type3_gen_2100(JKENERGY_KERNEL_ARGS)
{
    JKENERGY_KERNEL_SETUP();
    constexpr int nsq_per_block = 32;
    constexpr int gout_stride = 8;
    int t_id = gout_id * nsq_per_block + sq_id;
    int threads = nsq_per_block * gout_stride;
    int nbas = envs.nbas;
    int *bas = envs.bas;
    double *env = envs.env;
    int iprim = bounds.iprim;
    int jprim = bounds.jprim;
    int kprim = bounds.kprim;
    int lprim = bounds.lprim;
    int nroots = bounds.nroots;
    double *rlrk = shared_memory + sq_id;
    double *Rpq = shared_memory + nsq_per_block * 3 + sq_id;
    // the g arrays of the three directions, then the first-derivative factors of every tuple
    double *gx = shared_memory + nsq_per_block * 6 + sq_id;
    double *rw = shared_memory + nsq_per_block * 126 + sq_id;
    double *cicj_cache = shared_memory + nsq_per_block * (126+nroots*2);

    uint32_t *bas_kl_idx = pool + worker_id * QUEUE_DEPTH;
    double *dd_cache = dd_pool + worker_id * 576 + sq_id;
while (1) {
    __syncthreads();
    if (t_id == 0) {
        int task_id = atomicAdd(head, 1);
        int batch_kl = task_id / bounds.npairs_ij;
        pair_ij = task_id - bounds.npairs_ij * batch_kl;
        pair_kl0 = batch_kl * (QUEUE_DEPTH - 512);
        uint32_t bas_ij = bounds.pair_ij_mapping[pair_ij];
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    if (pair_kl0 >= bounds.npairs_kl) {
        break;
    }
    if (jk.lr_factor != 0) {
        _fill_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                        q_cond_ij, q_cond_kl,
                        (int *)shared_memory, jk, envs, bounds);
    } else {
        _fill_sr_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                           q_cond_ij, q_cond_kl,
                           s_cond_ij, s_cond_kl, diffuse_exps,
                           (int *)shared_memory, jk, envs, bounds);
    }
    if (ntasks == 0) {
        continue;
    }
    if (t_id == 0) {
        expi = bas[ish*BAS_SLOTS+PTR_EXP];
        expj = bas[jsh*BAS_SLOTS+PTR_EXP];
    }
    __syncthreads();
    if (t_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[t_id] = env[ri_ptr+t_id];
        rjri[t_id] = env[rj_ptr+t_id] - ri[t_id];
    }
    __syncthreads();
    double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
    double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
    double xjxi = rjri[0];
    double yjyi = rjri[1];
    double zjzi = rjri[2];
    for (int ij = t_id; ij < iprim*jprim; ij += threads) {
        int ip = ij / jprim;
        int jp = ij % jprim;
        double ai = env[expi+ip];
        double aj = env[expj+jp];
        double aij = ai + aj;
        double theta_ij = ai * aj / aij;
        double rr_ij = xjxi*xjxi + yjyi*yjyi + zjzi*zjzi;
        double Kab = exp(-theta_ij * rr_ij);
        cicj_cache[ij] = ci[ip] * cj[jp] * Kab;
    }
    __syncthreads();

    int *ao_loc = envs.ao_loc;
    int nao = ao_loc[nbas];
    double *dm = jk.dm;

    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += nsq_per_block) {
        // another thread of this quartet may still read the previous task's dd_cache
        __syncthreads();
        uint32_t bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (ish*nbas+jsh == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        int i0 = ao_loc[ish];
        int j0 = ao_loc[jsh];
        int k0 = ao_loc[ksh];
        int l0 = ao_loc[lsh];
        int expk = bas[ksh*BAS_SLOTS+PTR_EXP];
        int expl = bas[lsh*BAS_SLOTS+PTR_EXP];
        int ck = bas[ksh*BAS_SLOTS+PTR_COEFF];
        int cl = bas[lsh*BAS_SLOTS+PTR_COEFF];
        int rk = bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        int rl = bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        double xlxk = env[rl+0] - env[rk+0];
        double ylyk = env[rl+1] - env[rk+1];
        double zlzk = env[rl+2] - env[rk+2];
        if (gout_id == 0) {
            rlrk[0] = xlxk;
            rlrk[32] = ylyk;
            rlrk[2*32] = zlzk;
        }
        double vik_xx = 0;
        double vik_xy = 0;
        double vik_xz = 0;
        double vik_yx = 0;
        double vik_yy = 0;
        double vik_yz = 0;
        double vik_zx = 0;
        double vik_zy = 0;
        double vik_zz = 0;
        double vjk_xx = 0;
        double vjk_xy = 0;
        double vjk_xz = 0;
        double vjk_yx = 0;
        double vjk_yy = 0;
        double vjk_yz = 0;
        double vjk_zx = 0;
        double vjk_zy = 0;
        double vjk_zz = 0;
        double vil_xx = 0;
        double vil_xy = 0;
        double vil_xz = 0;
        double vil_yx = 0;
        double vil_yy = 0;
        double vil_yz = 0;
        double vil_zx = 0;
        double vil_zy = 0;
        double vil_zz = 0;
        double vjl_xx = 0;
        double vjl_xy = 0;
        double vjl_xz = 0;
        double vjl_yx = 0;
        double vjl_yy = 0;
        double vjl_yz = 0;
        double vjl_zx = 0;
        double vjl_zy = 0;
        double vjl_zz = 0;
        int do_j = jk.j_factor != 0.;
        int do_k = jk.k_factor != 0.;
        if (jk.n_dm == 1) {
            for (int n = gout_id; n < 18; n+=8) {
                int i = n % 6;
                int j = n / 6 % 3;
                int k = n / 18 % 1;
                int l = n / 18;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _il = _i*nao+_l;
                int _ik = _i*nao+_k;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += jk.k_factor * (dm[_jk] * dm[_il] + dm[_jl] * dm[_ik]);
                }
                if (do_j) {
                    dd += jk.j_factor * dm[_ji] * dm[_lk];
                }
                dd_cache[n*32] = fac_sym * dd;
            }
        } else {
            double *dmb = dm + nao * nao;
            for (int n = gout_id; n < 18; n+=8) {
                int i = n % 6;
                int j = n / 6 % 3;
                int k = n / 18 % 1;
                int l = n / 18;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _il = _i*nao+_l;
                int _ik = _i*nao+_k;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += dm [_jk] * dm [_il] + dm [_jl] * dm [_ik];
                    dd += dmb[_jk] * dmb[_il] + dmb[_jl] * dmb[_ik];
                    dd *= jk.k_factor;
                }
                if (do_j) {
                    dd += jk.j_factor * (dm[_ji] + dmb[_ji]) * (dm[_lk] + dmb[_lk]);
                }
                dd_cache[n*32] = fac_sym * dd;
            }
        }
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            int kp = klp / lprim;
            int lp = klp % lprim;
            double ak = env[expk+kp];
            double al = env[expl+lp];
            double ak2 = ak * 2;
            double al2 = al * 2;
            double akl = ak + al;
            double al_akl = al / akl;
            double theta_kl = ak * al_akl;
            __syncthreads();
            if (gout_id == 0) {
                double Kcd = exp(-theta_kl * (xlxk*xlxk+ylyk*ylyk+zlzk*zlzk));
                double ckcl = env[ck+kp] * env[cl+lp] * Kcd;
                gx[0] = ckcl;
            }
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                if (fabs(cicj_cache[ijp]) < PRIM_CUTOFF) continue;
                int ip = ijp / jprim;
                int jp = ijp % jprim;
                double ai = env[expi+ip];
                double aj = env[expj+jp];
                double ai2 = ai * 2;
                double aj2 = aj * 2;
                double aij = ai + aj;
                double aj_aij = aj / aij;
                double xij = ri[0] + rjri[0] * aj_aij;
                double yij = ri[1] + rjri[1] * aj_aij;
                double zij = ri[2] + rjri[2] * aj_aij;
                double xkl = env[rk+0] + xlxk * al_akl;
                double ykl = env[rk+1] + ylyk * al_akl;
                double zkl = env[rk+2] + zlzk * al_akl;
                double xpq = xij - xkl;
                double ypq = yij - ykl;
